27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final AddressNormalizer addressNormalizer;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 TelephoneNormalizer telephoneNormalizer,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.telephoneNormalizer = telephoneNormalizer;
89	        this.addressNormalizer = addressNormalizer;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        normalizeAndValidate(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
124	        assignHousehold(owner, ownerFieldsDto);
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    /**
133	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
134	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
135	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
136	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
137	     * it; the email is canonicalized; and a missing registration date defaults to the current date. The payload is
138	     * mutated in place so the caller can map and save it directly.
139	     *
140	     * @param ownerFieldsDto the incoming owner payload, mutated in place
141	     * @throws MissingOwnerFieldsException if any required field is missing or blank
142	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
143	     */
144	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
145	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
146	        validateRequiredFields(ownerFieldsDto);
147	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
148	        ownerFieldsDto.setTelephone(telephone);
149	        requireUniqueTelephone(telephone);
150	        requireUniqueHousehold(ownerFieldsDto);
151	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
152	        if (ownerFieldsDto.getRegistrationDate() == null) {
153	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
154	        }
155	    }
156	
157	    /**
158	     * Builds an owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}. {@code LAST3} is the upper-cased first
159	     * three letters of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than
160	     * the current number of owners (e.g. {@code SMI-0007}).
161	     *
162	     * @param lastName the owner's last name
163	     * @return the generated customer code
164	     */
165	    private String generateCustomerCode(String lastName) {
166	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
167	        int sequence = this.clinicService.findAllOwners().size() + 1;
168	        return String.format("%s-%04d", prefix, sequence);
169	    }
170	
171	    /**
172	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
173	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
174	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
175	     *
176	     * @param ownerFieldsDto the owner payload to validate
177	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
178	     */
179	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
180	        List<String> missingFields = new ArrayList<>();
181	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
182	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
183	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
184	        requireText(missingFields, "city", ownerFieldsDto.getCity());
185	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
186	        if (!missingFields.isEmpty()) {
187	            throw new MissingOwnerFieldsException(missingFields);
188	        }
189	    }
190	
191	    private void requireText(List<String> missingFields, String fieldName, String value) {
192	        if (value == null || value.isBlank()) {
193	            missingFields.add(fieldName);
194	        }
195	    }
196	
197	    /**
198	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
199	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
200	     * (blank or {@code null}) email is left untouched, since the field is optional.
201	     *
202	     * @param email the raw email value from the request, may be {@code null}
203	     * @return the lower-cased email, or the original value when none was supplied
204	     */
205	    private String normalizeEmail(String email) {
206	        if (email == null || email.isBlank()) {
207	            return email;
208	        }
209	        return email.toLowerCase();
210	    }
211	
212	    /**
213	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
214	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
215	     * originally formatted.
216	     *
217	     * @param telephone the normalized telephone of the owner being created
218	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
219	     */
220	    private void requireUniqueTelephone(String telephone) {
221	        boolean inUse = this.clinicService.findAllOwners().stream()
222	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
223	            .anyMatch(telephone::equals);
224	        if (inUse) {
225	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
226	        }
227	    }
228	
229	    /**
230	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
231	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
232	     *
233	     * @param ownerFieldsDto the incoming owner payload
234	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
235	     *                                 set {@code sharesHousehold}
236	     */
237	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
238	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
239	            return;
240	        }
241	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
242	            throw new DuplicateOwnerException(
243	                "an owner with the same last name and address already exists in this household");
244	        }
245	    }
246	
247	    /**
248	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
249	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
250	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
251	     * incidental formatting differences and abbreviation variants do not affect membership.
252	     *
253	     * @param ownerFieldsDto the incoming owner payload
254	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
255	     *         them; empty when none match
256	     */
257	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
258	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
259	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
260	        return this.clinicService.findAllOwners().stream()
261	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
262	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
263	            .toList();
264	    }
265	
266	    /**
267	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
268	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
269	     *
270	     * @param value the raw field value, may be {@code null}
271	     * @return the whitespace-collapsed value, or an empty string when {@code null}
272	     */
273	    private String collapseWhitespace(String value) {
274	        if (value == null) {
275	            return "";
276	        }
277	        return value.strip().replaceAll("\\s+", " ");
278	    }
279	
280	    /**
281	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
282	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
283	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
284	     * identifier is derived deterministically from the household's last name and address, so every member of the same
285	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
286	     * feature and still lack the identifier are backfilled so the whole household shares it.
287	     *
288	     * @param owner          the newly mapped owner about to be saved
289	     * @param ownerFieldsDto the incoming owner payload
290	     */
291	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
292	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
293	            return;
294	        }
295	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
296	        if (members.isEmpty()) {
297	            return;
298	        }
299	        String householdId = generateHouseholdId(ownerFieldsDto);
300	        owner.setHouseholdId(householdId);
301	        for (Owner member : members) {
302	            if (!householdId.equals(member.getHouseholdId())) {
303	                member.setHouseholdId(householdId);
304	                this.clinicService.saveOwner(member);
305	            }
306	        }
307	    }
308	
309	    /**
310	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
311	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
312	     * of those fields, it is identical for every owner in the same household and never changes over time.
313	     *
314	     * @param ownerFieldsDto the incoming owner payload
315	     * @return the household identifier
316	     */
317	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
318	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
319	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
320	        try {
321	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
322	            StringBuilder hex = new StringBuilder();
323	            for (int i = 0; i < 6; i++) {
324	                hex.append(String.format("%02X", digest[i]));
325	            }
326	            return "HH-" + hex;
327	        } catch (NoSuchAlgorithmException ex) {
328	            throw new IllegalStateException("SHA-256 is not available", ex);
329	        }
330	    }
331	
332	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
333	    @Override
334	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
335	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
336	        if (currentOwner == null) {
337	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
338	        }
339	        currentOwner.setAddress(ownerFieldsDto.getAddress());
340	        currentOwner.setCity(ownerFieldsDto.getCity());
341	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
342	        currentOwner.setLastName(ownerFieldsDto.getLastName());
343	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
344	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
345	        this.clinicService.saveOwner(currentOwner);
346	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
347	    }
348	
349	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
350	    @Transactional
351	    @Override
352	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
353	        Owner owner = this.clinicService.findOwnerById(ownerId);
354	        if (owner == null) {
355	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	        }
357	        this.clinicService.deleteOwner(owner);
358	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
364	        Owner owner = this.clinicService.findOwnerById(ownerId);
365	        if (owner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        HttpHeaders headers = new HttpHeaders();
369	        Pet pet = petMapper.toPet(petFieldsDto);
370	        owner.setId(ownerId);
371	        pet.setOwner(owner);
372	        pet.getType().setName(null);
373	        this.clinicService.savePet(pet);
374	        PetDto petDto = petMapper.toPetDto(pet);
375	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
376	            .buildAndExpand(pet.getId()).toUri());
377	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Override
382	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
383	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
384	        if (currentOwner != null) {
385	            Pet currentPet = this.clinicService.findPetById(petId);
386	            if (currentPet != null) {
387	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
388	                currentPet.setName(petFieldsDto.getName());
389	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
390	                this.clinicService.savePet(currentPet);
391	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
392	            }
393	        }
394	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
395	    }
396	
397	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
398	    @Override
399	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
400	        HttpHeaders headers = new HttpHeaders();
401	        Visit visit = visitMapper.toVisit(visitFieldsDto);
402	        Pet pet = new Pet();
403	        pet.setId(petId);
404	        visit.setPet(pet);
405	        this.clinicService.saveVisit(visit);
406	        VisitDto visitDto = visitMapper.toVisitDto(visit);
407	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
408	            .buildAndExpand(visit.getId()).toUri());
409	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
410	    }
411	
412	
413	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
414	    @Override
415	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
416	        Owner owner = this.clinicService.findOwnerById(ownerId);
417	        if (owner != null) {
418	            Pet pet = owner.getPet(petId);
419	            if (pet != null) {
420	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
421	            }
422	        }
423	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
424	    }
425	}
